import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.BQv2qOVx.js";const s="/aibutler/docs-versions/v1.1.10/img/en/chat-chart.png",m=JSON.parse('{"title":"What the Chat Window Can Show","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/display.md","filePath":"en/guide/display.md"}'),i={name:"en/guide/display.md"};function r(h,a,l,d,p,c){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="what-the-chat-window-can-show" tabindex="-1">What the Chat Window Can Show <a class="header-anchor" href="#what-the-chat-window-can-show" aria-label="Permalink to &quot;What the Chat Window Can Show&quot;">​</a></h1><p>A persona&#39;s replies aren&#39;t limited to text. The chat window can draw tables, charts, flowcharts, formulas, and animations directly, and it can show forms with input fields and buttons.</p><p><strong>You don&#39;t need to learn any special syntax</strong> — just tell it what you want to see.</p><p><img src="'+s+'" alt="A table and a bar chart"></p><div class="tip custom-block"><p class="custom-block-title">Tool calls are hidden by default</p><p>The tools a persona calls while working are not listed line by line in the chat by default; the status bar at the bottom of the window shows what it&#39;s doing. To see them, open Settings → <strong>General</strong> → <strong>Tool calls</strong> and check <strong>Show in the conversation</strong>. <strong>Tips</strong> on the same page controls the usage tip shown at each startup — turn it off, or click <strong>Show one now</strong>.</p></div><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><blockquote><p>List this week&#39;s expenses by category in a table.</p></blockquote><p>Good for comparisons, lists, and ledgers.</p><h2 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h2><blockquote><p>Draw a bar chart of my spending each month over the last six months.</p></blockquote><blockquote><p>Show my weight trend with a line chart.</p></blockquote><p>Bar charts, line charts, and pie charts are all supported.</p><h2 id="flowcharts-and-diagrams" tabindex="-1">Flowcharts and diagrams <a class="header-anchor" href="#flowcharts-and-diagrams" aria-label="Permalink to &quot;Flowcharts and diagrams&quot;">​</a></h2><blockquote><p>Draw a flowchart of the steps for filing an expense report.</p></blockquote><blockquote><p>Draw a diagram showing how these personas divide up the work.</p></blockquote><h2 id="formulas" tabindex="-1">Formulas <a class="header-anchor" href="#formulas" aria-label="Permalink to &quot;Formulas&quot;">​</a></h2><blockquote><p>Write out the compound interest formula and explain each variable.</p></blockquote><p>Math and physics formulas are typeset properly.</p><h2 id="graphics-and-animation" tabindex="-1">Graphics and animation <a class="header-anchor" href="#graphics-and-animation" aria-label="Permalink to &quot;Graphics and animation&quot;">​</a></h2><blockquote><p>Draw a diagram of the solar system, with the planets orbiting.</p></blockquote><p>Good for explaining how something works, or for demos.</p><h2 id="forms-and-buttons" tabindex="-1">Forms and buttons <a class="header-anchor" href="#forms-and-buttons" aria-label="Permalink to &quot;Forms and buttons&quot;">​</a></h2><p>When it needs you to fill something in or make a choice, the persona puts input fields, dropdowns, radio buttons, checkboxes, and buttons right in the chat — just click, no typing needed. For example:</p><blockquote><p>Set a reminder for me — ask me for the time and what it&#39;s about.</p></blockquote><p>It will pop up a small form asking for the time and details, with a button to submit.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><p>For an interface you want to keep around — an expense tracker, a to-do board, flashcards — have it turned into a <a href="/aibutler/docs-versions/v1.1.10/en/guide/plugins.html">plugin</a>. Plugins can be pinned to the side of the window and opened any time.</p><h2 id="side-panels-and-bookmarks" tabindex="-1">Side panels and Bookmarks <a class="header-anchor" href="#side-panels-and-bookmarks" aria-label="Permalink to &quot;Side panels and Bookmarks&quot;">​</a></h2><p>Click ◫ in the top bar to switch between the stacked and side-panel layouts. Each persona remembers its own choice.</p><p>With side panels, reminders, to-dos and quick buttons move to the left, the chat stays in the middle, and the right holds <strong>Bookmarks</strong>: tell the persona &quot;bookmark this&quot; and that reply is saved there — a plan you settled on, a result it worked out, a file path it handed you. However far the chat has scrolled, click one to expand the full text in place; the small buttons beside it jump back to the original message or delete it.</p><p>Both panels can be resized: drag the edge between a panel and the chat. Drag it all the way to the window edge and the panel folds into a thin strip; bookmarks still land in it while folded, and the right strip shows how many are new. Click the strip or drag it back out to reopen the panel.</p><p>In the stacked layout, a number appears on ◫ when new bookmarks arrive; switch to side panels to see them. When the window is narrower than 1100 pixels it falls back to stacked and ◫ is hidden until you widen it again.</p>',32)])])}const b=e(i,[["render",r]]);export{m as __pageData,b as default};
